def find_Sum(arr,n):
    """
    Write a python function to find the sum of repeated elements in a given array.
    >>> find_Sum([1,2,3,1,1,4,5,6],8)
    3
    >>> find_Sum([1,2,3,1,1],5)
    3
    >>> find_Sum([1,1,2],3)
    2
    """
def find_Sum(arr, n):
    element_count = {}
    sum_repeated = 0
    for num in arr:
        if num in element_count:
            element_count[num] += 1
        else:
            element_count[num] = 1
    for num, count in element_count.items():
        if count > 1:
            sum_repeated += num
    return sum_repeated

