def extract_missing(test_list, strt_val, stop_val):
  """
  Write a function to extract the ranges that are missing from the given list with the given start range and end range values.
  >>> extract_missing([(6, 9), (15, 34), (48, 70)], 2, 100)
  [(2, 6), (9, 100), (9, 15), (34, 100), (34, 48), (70, 100)]
  >>> extract_missing([(7, 2), (15, 19), (38, 50)], 5, 60)
  [(5, 7), (2, 60), (2, 15), (19, 60), (19, 38), (50, 60)]
  >>> extract_missing([(7, 2), (15, 19), (38, 50)], 1, 52)
  [(1, 7), (2, 52), (2, 15), (19, 52), (19, 38), (50, 52)]
  """
def extract_missing(test_list, strt_val, stop_val):
    missing_ranges = []
    prev_end = strt_val
    for start, end in sorted(test_list):
        if prev_end < start:
            missing_ranges.append((prev_end, start))
        prev_end = max(prev_end, end)
    if prev_end < stop_val:
        missing_ranges.append((prev_end, stop_val))
    additional_ranges = []
    for i, (start1, end1) in enumerate(test_list):
        for start2, end2 in test_list[i + 1:]:
            if end1 < start2:
                additional_ranges.append((end1, start2))
        if end1 < stop_val:
            additional_ranges.append((end1, stop_val))
    return missing_ranges + additional_ranges

