  '[(4, 2, 4, 2), (7, 1, 2), (4, 8, 1), (9, 2, 1)]'
  >>> assign_freq([(11, 13, 10), (17, 21), (4, 2, 3), (17, 21), (9, 2), (4, 2, 3)] )
  '[(11, 13, 10, 1), (17, 21, 2), (4, 2, 3, 2), (9, 2, 1)]'
  """
def assign_freq(test_list):
    freq_dict = {}
    result = []
    for tup in test_list:
        freq_dict[tup] = freq_dict.get(tup, 0) + 1
    for tup in freq_dict:
        result.append(tup + (freq_dict[tup],))
    return str(result)

