    """
    Write a python function to find the first missing positive number.
    >>> first_Missing_Positive([1,2,3,-1,5],5)
    4
    >>> first_Missing_Positive([0,-1,-2,1,5,8],6)
    2
    >>> first_Missing_Positive([0,1,2,5,-8],5)
    3
    """
def first_Missing_Positive(arr, n):
    for i in range(n):
        while 1 <= arr[i] <= n and arr[arr[i] - 1] != arr[i]:
            arr[arr[i] - 1], arr[i] = (arr[i], arr[arr[i] - 1])
    for i in range(n):
        if arr[i] != i + 1:
            return i + 1
    return n + 1

