def get_total_number_of_sequences(m,n):
	"""
	Write a function to find the number of possible sequences of length n such that each of the next element is greater than or equal to twice of the previous element but less than or equal to m.
	>>> get_total_number_of_sequences(10, 4)
	4
	>>> get_total_number_of_sequences(5, 2)
	6
	>>> get_total_number_of_sequences(16, 3)
	84
	"""
def get_total_number_of_sequences(m, n):

	def count_sequences(start, remaining_length):
		if remaining_length == 0:
			return 1
		return sum((count_sequences(next_value, remaining_length - 1) for next_value in range(2 * start, 1 + m)))
	return sum((count_sequences(start_value, n - 1) for start_value in range(1, 1 + m)))

