    (True, 7)
    >>> sequential_search([9, 10, 17, 19, 22, 39, 48, 56],48)
    (True, 6)
    """
def sequential_search(dlist, item):
    for index, value in enumerate(dlist):
        if value == item:
            return (True, index)
    return (False, -1)

