def max_aggregate(stdata):
    """
    Write a function to calculate the maximum aggregate from the list of tuples.
    >>> max_aggregate([('Juan Whelan',90),('Sabah Colley',88),('Peter Nichols',7),('Juan Whelan',122),('Sabah Colley',84)])
    ('Juan Whelan', 212)
    >>> max_aggregate([('Juan Whelan',50),('Sabah Colley',48),('Peter Nichols',37),('Juan Whelan',22),('Sabah Colley',14)])
    ('Juan Whelan', 72)
    >>> max_aggregate([('Juan Whelan',10),('Sabah Colley',20),('Peter Nichols',30),('Juan Whelan',40),('Sabah Colley',50)])
    ('Sabah Colley', 70)
    """
def max_aggregate(stdata):
    aggregates = {}
    for name, score in stdata:
        if name in aggregates:
            aggregates[name] += score
        else:
            aggregates[name] = score
    return max(aggregates.items(), key=lambda x: x[1])

