def solve(a,n):
    """
    Write a python function to check whether the count of inversion of two types are same or not.
    >>> solve([1,0,2],3)
    True
    >>> solve([1,2,0],3)
    False
    >>> solve([1,2,1],3)
    True
    """
def solve(a, n):
    type1 = 0
    type2 = 0
    for i in range(n):
        for j in range(i + 1, n):
            if a[i] > a[j]:
                type1 += 1
            if a[i] < a[j]:
                type2 += 1
    return type1 == type2

