def zigzag(n, k):
	"""
	Write a function to find entringer number e(n, k).
	>>> zigzag(4, 3)
	5
	>>> zigzag(4, 2)
	4
	>>> zigzag(3, 1)
	1
	"""
def zigzag(n, k):
    if n == 0 and k == 0:
        return 1
    elif k < 0 or k > n:
        return 0
    return zigzag(n - 1, k - 1) + zigzag(n - 1, n - k)

