def get_max_sum (n):
	"""
	Write a function to find the maximum sum possible by using the given equation f(n) = max( (f(n/2) + f(n/3) + f(n/4) + f(n/5)), n).
	>>> get_max_sum(60)
	106
	>>> get_max_sum(10)
	12
	>>> get_max_sum(2)
	2
	"""
def get_max_sum(n):
    memo = {0: 0}

    def f(x):
        if x in memo:
            return memo[x]
        memo[x] = max(f(x // 2) + f(x // 3) + f(x // 4) + f(x // 5), x)
        return memo[x]
    return f(n)

