def max_Product(arr):
    """
    Write a python function to find a pair with highest product from a given array of integers.
    >>> max_Product([1,2,3,4,7,0,8,4])
    (7,8)
    >>> max_Product([0,-1,-2,-4,5,0,-6])
    (-4,-6)
    >>> max_Product([1,2,3])
    (2,3)
    """
def max_Product(arr):
    max1, max2 = (0, 0)
    min1, min2 = (0, 0)
    for num in arr:
        if num > max1:
            max2 = max1
            max1 = num
        elif num > max2:
            max2 = num
        if num < min1:
            min2 = min1
            min1 = num
        elif num < min2:
            min2 = num
    if max1 * max2 > min1 * min2:
        return (max2, max1)
    else:
        return (min2, min1)

