def max_product(arr, n ):
	"""
	Write a function to find the maximum product formed by multiplying numbers of an increasing subsequence of that array.
	>>> max_product([3, 100, 4, 5, 150, 6], 6)
	45000
	>>> max_product([4, 42, 55, 68, 80], 5)
	50265600
	>>> max_product([10, 22, 9, 33, 21, 50, 41, 60], 8)
	21780000
	"""
def max_product(arr, n):
	dp = []
	for _ in range(n):
		list.append(dp, 0)
	for i in range(n):
		dp[i] = arr[i]
	for i in range(1, n):
		for j in range(i):
			if arr[j] < arr[i]:
				dp[i] = max(dp[i], dp[j] * arr[i])
	return max(dp)

