def extract_symmetric(test_list):
  """
  Write a function to extract all the pairs which are symmetric in the given tuple list.
  >>> extract_symmetric([(6, 7), (2, 3), (7, 6), (9, 8), (10, 2), (8, 9)] )
  {(8, 9), (6, 7)}
  >>> extract_symmetric([(7, 8), (3, 4), (8, 7), (10, 9), (11, 3), (9, 10)] )
  {(9, 10), (7, 8)}
  >>> extract_symmetric([(8, 9), (4, 5), (9, 8), (11, 10), (12, 4), (10, 11)] )
  {(8, 9), (10, 11)}
  """
def extract_symmetric(test_list):
    seen = set()
    symmetric_pairs = set()
    for a, b in test_list:
        if (b, a) in seen:
            symmetric_pairs.add((min(a, b), max(a, b)))
        seen.add((a, b))
    return symmetric_pairs

def extract_symmetric(test_list):
  """
  Write a function to extract all the pairs which are symmetric in the given tuple list.
  >>> extract_symmetric([(6, 7), (2, 3), (7, 6), (9, 8), (10, 2), (8, 9)] )
  {(8, 9), (6, 7)}
  >>> extract_symmetric([(7, 8), (3, 4), (8, 7), (10, 9), (11, 3), (9, 10)] )
  {(9, 10), (7, 8)}
  >>> extract_symmetric([(8, 9), (4, 5), (9, 8), (11, 10), (12, 4), (10, 11)] )
  {(8, 9), (10, 11)}
  """
def extract_symmetric(test_list):
	seen = set()
	symmetric_pairs = set()
	for a, b in test_list:
		if (b, a) in seen:
			set.add(symmetric_pairs, (min(a, b), max(a, b)))
		set.add(seen, (a, b))
	return symmetric_pairs

