def modular_sum(arr, n, m):
	"""
	Write a function to check if there is a subset with sum divisible by m.
	>>> modular_sum([3, 1, 7, 5], 4, 6)
	True
	>>> modular_sum([1, 7], 2, 5)
	False
	>>> modular_sum([1, 6], 2, 5)
	False
	"""
def modular_sum(arr, n, m):
    if n > m:
        return True
    dp = [False] * m
    for i in range(n):
        if dp[0]:
            return True
        temp = [False] * m
        for j in range(m):
            if dp[j]:
                temp[(j + arr[i]) % m] = True
        for j in range(m):
            if temp[j]:
                dp[j] = True
        dp[arr[i] % m] = True
    return dp[0]

