  Write a function to find the lcm of the given array elements.
  >>> get_lcm([2, 7, 3, 9, 4])
  252
  >>> get_lcm([1, 2, 8, 3])
  24
  >>> get_lcm([3, 8, 4, 10, 5])
  120
  """
def gcd(a, b):
    while b:
        a, b = (b, a % b)
    return a

def lcm(a, b):
    return abs(a * b) // gcd(a, b)

def get_lcm(l):
    current_lcm = l[0]
    for num in l[1:]:
        current_lcm = lcm(current_lcm, num)
    return current_lcm

