 >>> search_literal('python','python programming language')
 (0,6)
 >>> search_literal('programming','python programming language')
 (7,18)
 >>> search_literal('language','python programming language')
 (19,27)
 """
def search_literal(pattern, text):
    start = text.find(pattern)
    if start == -1:
        return None
    end = start + len(pattern)
    return (start, end)

