def find_kth(arr1, arr2, m, n, k):
	"""
	Write a function to find kth element from the given two sorted arrays.
	>>> find_kth([2, 3, 6, 7, 9], [1, 4, 8, 10], 5, 4, 5)
	6
	>>> find_kth([100, 112, 256, 349, 770], [72, 86, 113, 119, 265, 445, 892], 5, 7, 7)
	256
	>>> find_kth([3, 4, 7, 8, 10], [2, 5, 9, 11], 5, 4, 6)
	8
	"""
def find_kth(arr1, arr2, m, n, k):
    if m > n:
        return find_kth(arr2, arr1, n, m, k)
    if m == 0:
        return arr2[k - 1]
    if k == 1:
        return min(arr1[0], arr2[0])
    i = min(m, k // 2)
    j = min(n, k // 2)
    if arr1[i - 1] > arr2[j - 1]:
        return find_kth(arr1, arr2[j:], m, n - j, k - j)
    else:
        return find_kth(arr1[i:], arr2, m - i, n, k - i)

def find_kth(arr1, arr2, m, n, k):
	"""
	Write a function to find kth element from the given two sorted arrays.
	>>> find_kth([2, 3, 6, 7, 9], [1, 4, 8, 10], 5, 4, 5)
	6
	>>> find_kth([100, 112, 256, 349, 770], [72, 86, 113, 119, 265, 445, 892], 5, 7, 7)
	256
	>>> find_kth([3, 4, 7, 8, 10], [2, 5, 9, 11], 5, 4, 6)
	8
	"""
def find_kth(arr1, arr2, m, n, k):
	if m > n:
		return find_kth(arr2, arr1, n, m, k)
	if m == 0:
		return arr2[k - 1]
	if k == 1:
		return min(arr1[0], arr2[0])
	i = min(m, k // 2)
	j = min(n, k // 2)
	if arr2[j - 1] < arr1[i - 1]:
		return find_kth(arr1, arr2[j:], m, n - j, k - j)
	return find_kth(arr1[i:], arr2, m - i, n, k - i)

