	"""
	Write a function to find the largest subset where each pair is divisible.
	>>> largest_subset([ 1, 3, 6, 13, 17, 18 ], 6)
	4
	>>> largest_subset([10, 5, 3, 15, 20], 5)
	3
	>>> largest_subset([18, 1, 3, 6, 13, 17], 6)
	4
	"""
def largest_subset(a, n):
	a = sorted(a)
	dp = []
	for _ in range(n):
		list.append(dp, 1)
	for i in range(1, n):
		for j in range(i):
			if a[i] % a[j] == 0 or a[j] % a[i] == 0:
				dp[i] = max(dp[i], dp[j] + 1)
	return max(dp)

