def sum_Of_Primes(n):
    """
    Write a python function to find sum of prime numbers between 1 to n.
    >>> sum_Of_Primes(10)
    17
    >>> sum_Of_Primes(20)
    77
    >>> sum_Of_Primes(5)
    10
    """
def sum_Of_Primes(n):

    def is_prime(num):
        if num <= 1:
            return False
        if num <= 3:
            return True
        if num % 2 == 0 or num % 3 == 0:
            return False
        i = 5
        while i * i <= num:
            if num % i == 0 or num % (i + 2) == 0:
                return False
            i += 6
        return True
    return sum((i for i in range(2, n + 1) if is_prime(i)))

