def jacobsthal_num(n):
	"""
	Write a function to find the nth jacobsthal number.
	>>> jacobsthal_num(5)
	11
	>>> jacobsthal_num(2)
	1
	>>> jacobsthal_num(4)
	5
	"""
def jacobsthal_num(n):
    if n == 0:
        return 0
    elif n == 1:
        return 1
    else:
        return jacobsthal_num(n - 1) + 2 * jacobsthal_num(n - 2)

