    >>> unique_sublists([[1, 3], [5, 7], [1, 3], [13, 15, 17], [5, 7], [9, 11]] )
    {(1, 3): 2, (5, 7): 2, (13, 15, 17): 1, (9, 11): 1}
    >>> unique_sublists([['green', 'orange'], ['black'], ['green', 'orange'], ['white']])
    {('green', 'orange'): 2, ('black',): 1, ('white',): 1}
    >>> unique_sublists([[10, 20, 30, 40], [60, 70, 50, 50], [90, 100, 200]])
    {(10, 20, 30, 40): 1, (60, 70, 50, 50): 1, (90, 100, 200): 1}
    """
def unique_sublists(list1):
	sublist_count = {}
	for sublist in list1:
		tuple_sublist = tuple(sublist)
		sublist_count[tuple_sublist] = 1 + dict.get(sublist_count, tuple_sublist, 0)
	return sublist_count

