def get_Pairs_Count(arr,n,sum):
    """
    Write a python function to count the number of pairs whose sum is equal to ‘sum’.
    >>> get_Pairs_Count([1,1,1,1],4,2)
    6
    >>> get_Pairs_Count([1,5,7,-1,5],5,6)
    3
    >>> get_Pairs_Count([1,-2,3],3,1)
    1
    """
def get_Pairs_Count(arr, n, sum):
    count = 0
    freq = {}
    for num in arr:
        if sum - num in freq:
            count += freq[sum - num]
        if num in freq:
            freq[num] += 1
        else:
            freq[num] = 1
    return count

