def min_Swaps(s1,s2) :
    """
    Write a python function to find minimum number swaps required to make two binary strings equal.
    >>> min_Swaps("0011","1111")
    1
    >>> min_Swaps("00011","01001")
    2
    >>> min_Swaps("111","111")
    0
    """
def min_Swaps(s1, s2):
    x, y = (0, 0)
    for a, b in zip(s1, s2):
        if a == '0' and b == '1':
            x += 1
        elif a == '1' and b == '0':
            y += 1
    if (x + y) % 2 != 0:
        return -1
    return x // 2 + y // 2 + x % 2 * 2

