def check(arr,n):
    """
    Write a python function to check whether an array can be sorted or not by picking only the corner elements.
    >>> check([3,2,1,2,3,4],6)
    True
    >>> check([2,1,4,5,1],5)
    True
    >>> check([1,2,2,1,2,3],6)
    True
    """
def check(arr, n):
    left, right = (0, n - 1)
    prev = float('-inf')
    while left <= right:
        if arr[left] <= arr[right]:
            if arr[left] >= prev:
                prev = arr[left]
                left += 1
            else:
                return False
        elif arr[right] >= prev:
            prev = arr[right]
            right -= 1
        else:
            return False
    return True

