	for i in range(arr_size - 2):
		left = i + 1
		right = arr_size - 1
		while left < right:
			current_sum = A[left] + A[i] + A[right]
			if current_sum == sum:
				return (A[i], A[left], A[right])
			elif current_sum < sum:
				left += 1
			else:
				right -= 1
	return None

