def coin_change(S, m, n):
    """
    Write a function to count coin change.
    >>> coin_change([1, 2, 3],3,4)
    4
    >>> coin_change([4,5,6,7,8,9],6,9)
    2
    >>> coin_change([4,5,6,7,8,9],6,4)
    1
    """
def coin_change(S, m, n):
    if n == 0:
        return 1
    if n < 0 or m <= 0:
        return 0
    return coin_change(S, m - 1, n) + coin_change(S, m, n - S[m - 1])

