    Write a function to find a pair with the highest product from a given array of integers.
    >>> max_product([1, 2, 3, 4, 7, 0, 8, 4])
    (7, 8)
    >>> max_product([0, -1, -2, -4, 5, 0, -6])
    (-4, -6)
    >>> max_product([1, 3, 5, 6, 8, 9])
    (8,9)
    """
def max_product(arr):
    if len(arr) < 2:
        return None
    max1 = max2 = float('-inf')
    min1 = min2 = float('inf')
    for num in arr:
        if num > max1:
            max2 = max1
            max1 = num
        elif num > max2:
            max2 = num
        if num < min1:
            min2 = min1
            min1 = num
        elif num < min2:
            min2 = num
    if max1 * max2 > min1 * min2:
        return (max1, max2)
    else:
        return (min1, min2)

