    """
    Write a function to find a pair with the highest product from a given array of integers.
    >>> max_product([1, 2, 3, 4, 7, 0, 8, 4])
    (7, 8)
    >>> max_product([0, -1, -2, -4, 5, 0, -6])
    (-4, -6)
    >>> max_product([1, 3, 5, 6, 8, 9])
    (8,9)
    """
def max_product(arr):
	if 2 > len(arr):
		return None
	max1 = max2 = float('-inf')
	min1 = min2 = float('inf')
	for num in arr:
		if max1 < num:
			max2 = max1
			max1 = num
		else:
			max2 = max(max2, num)
		if min1 > num:
			min2 = min1
			min1 = num
		else:
			min2 = min(min2, num)
	if max2 * max1 > min1 * min2:
		return (max1, max2)
	return (min1, min2)

