def super_seq(X, Y, m, n):
	"""
	Write a function to find the length of the shortest string that has both str1 and str2 as subsequences.
	>>> super_seq("AGGTAB", "GXTXAYB", 6, 7)
	9
	>>> super_seq("feek", "eke", 4, 3)
	5
	>>> super_seq("PARRT", "RTA", 5, 3)
	6
	"""
def super_seq(X, Y, m, n):
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(m + 1):
        for j in range(n + 1):
            if i == 0:
                dp[i][j] = j
            elif j == 0:
                dp[i][j] = i
            elif X[i - 1] == Y[j - 1]:
                dp[i][j] = 1 + dp[i - 1][j - 1]
            else:
                dp[i][j] = 1 + min(dp[i - 1][j], dp[i][j - 1])
    return dp[m][n]

