def join_tuples(test_list):
  """
  Write a function to join the tuples if they have similar initial elements.
  >>> join_tuples([(5, 6), (5, 7), (6, 8), (6, 10), (7, 13)] )
  [(5, 6, 7), (6, 8, 10), (7, 13)]
  >>> join_tuples([(6, 7), (6, 8), (7, 9), (7, 11), (8, 14)] )
  [(6, 7, 8), (7, 9, 11), (8, 14)]
  >>> join_tuples([(7, 8), (7, 9), (8, 10), (8, 12), (9, 15)] )
  [(7, 8, 9), (8, 10, 12), (9, 15)]
  """
def join_tuples(test_list):
    result = []
    temp_dict = {}
    for tpl in test_list:
        if tpl[0] not in temp_dict:
            temp_dict[tpl[0]] = list(tpl)
        else:
            temp_dict[tpl[0]].extend(tpl[1:])
    for key, val in temp_dict.items():
        result.append(tuple(val))
    return result

def join_tuples(test_list):
